---@class UIMainInteractionCatDialog
local UIMainInteractionCatDialog = Class("UIMainInteractionCatDialog")

function UIMainInteractionCatDialog:__init() 
    self._catId = 0            --猫唯一id
    self._catData = nil        --猫数据

    self._catAniRandomTime = os.time()   --动作随机的时间
end

function UIMainInteractionCatDialog:__delete()
    self._catId = nil
    self._catData = nil
    self._catAniRandomTime = nil
end

function UIMainInteractionCatDialog:Awake()
end

function UIMainInteractionCatDialog:FillSelf()
    if not self._catData then
        return
    end
    KTool.SetActive(self.BtnRename.gameObject, not Constants.MODULE_SWITCH.Is_Read_Only)
    SetButtonAction(self.BtnRename, Bind(self, self.OnBtnRename))
    SetButtonAction(self.BtnCatHouse, Bind(self, self.OnBtnCatHouse))
    self._mainCatCellClick = Events.AddListener(Constants.EventNames.MainCatCellClick, Bind(self, self.OnMainCatCellClick))

    CfUtils.FillText(self.TextTitle, self._catData.name)
    local t = CfUtils.Split(self._catData.birthday, " ")
    if t then
        local t2 = CfUtils.Split(t[1], "-")
        CfUtils.FillText(self.TextBirth, t2[2].."-"..t2[3])
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", self._catData.catId)
    if vo then
        CfUtils.FillText(self.TextRace, vo.name)
    end
end

function UIMainInteractionCatDialog:OnBtnCatHouse()
    ---猫屋入口
    if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then
        return
    end

    cs_coroutine.start(function()
        CfUtils.SetActive(self.controller.gameObject, false)
        KCookie.Set(Constants.IsOpnePageing, 1)
        --[[
        local isShow = false
        GameUtils.ShowBlackOverlay(nil, function()
            while not isShow do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        ]]
        self._isGoCatHouse = true
        --coroutine.yield(UIModule.BackDialog())
        --isShow = true
        coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseMainDialog }, { { id = Constants.UITypeIds.UIMainInteractionCatDialog } }))
        KCookie.Set(Constants.IsOpnePageing, 0)
        --isShow = true
    end)
end

function UIMainInteractionCatDialog:OnBtnRename()
    CS.UINavigationBarRoot.Instance:SetActive(false)
    GameUtils.FourConfirm(localize("变更称呼"), self._catData.name, self._catData.name, nil, function(value)
        local length = utf8.len(value)
        local confirmSucceed = length <= MAX_NAME_LENGTH
        if confirmSucceed then
            GameUtils.Request(
                Interfaces.CatHouseRename, {playerCatId = self._catData.id, name = value}, function(request, response)
                    if checkInt(response.errCode) == 0 then
                        self._catData.name = value
                        GameUtils.Toast(localize("设置成功"))
                        CfUtils.FillText(self.TextTitle, self._catData.name)
                    end
                end
            )
        else
            GameUtils.Toast(localize("昵称最长7个字"))
        end
        CS.UINavigationBarRoot.Instance:SetActive(true)
    end, function()
        CS.UINavigationBarRoot.Instance:SetActive(true)
    end)
end

function UIMainInteractionCatDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetActive(self.controller.gameObject, false)
        local go = RolesShowMgr:GetInstance():GetInteractiveCam("Push_cat")
        CS.UINavigationBarRoot.Instance:SetActive(false)
        if go then
            KTool.SetActive(go, false)
        end
        CfUtils.SetTopCommonActive(false, true)
        CS.UINavigationBarRoot.Instance:SetActive(true)
        if not self._isGoCatHouse then
            coroutine.yield(CS.UnityEngine.WaitForSeconds(0.86))
        end
        CfUtils.ChangeMainCamDefalultBlend(0)
    end))
    return coWait
end

function UIMainInteractionCatDialog:Update()
    local seconds = os.time() - self._catAniRandomTime
    --五秒随一次
    if seconds >= 12 then
        seconds = os.time()
        if self._ani:IsPlaying("idle") then
            local num = math.random(3)
            local state = self._ani:TryPlay(string.format("lying%d", num))
            if not isNull(state) then
                state.Events:SetEndAction(function()
                    state.Events:SetEndAction(nil)
                    self._ani:TryPlay("idle")
                end)
            end
        end

        self._catAniRandomTime = os.time()
    end
end

function UIMainInteractionCatDialog:OnMainCatCellClick()
    --是idle的时候才响应
    if not self._ani:IsPlaying("idle") then
        return
    end

    if self._isAniPlay or isNull(self._go) then
        return
    end
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    local num = math.random(3)
    local state = self._ani:TryPlay(string.format("touch%d", num))
    if not isNull(state) then
        self._isAniPlay = true
        state.Events:SetEndAction(function()
            state.Events:SetEndAction(nil)
            self._isAniPlay = false
            self._ani:TryPlay('idle')
        end)
    end
end

function UIMainInteractionCatDialog:OnShow()
    ---显示主界面场景元素
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CS.UINavigationBarRoot.Instance:SetActive(true)
    end))
    return coWait
end

function UIMainInteractionCatDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.RefeshSystemToggleId(self.BtnCatHouse, Constants.SystemToggleIds.Id234)
        
        --local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
        --local t = component:GetBlindBoxData()

        GameUtils.BindRedPoint(Constants.RedPointConst.CatHouse, self.BtnCatHouse, true, nil, function(node)
            local redPointGo = GameUtils.GetRedPointGo(self.BtnCatHouse)
            if not redPointGo then
                return
            end
            local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id234)
            if not isUnlock then
                KTool.SetActive(redPointGo, false)
                return
            end
            if node.pointNum == 1 then
                KTool.SetActive(redPointGo, true)
            else
                --额外判断一次盲盒
                local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
                local t = component:GetBlindBoxData()
                local go = GameUtils.GetRedPointGo(self.BtnCatHouse)
                if go then
                    KTool.SetActive(redPointGo, table.count(t) > 0)
                end
            end
        end)
        --[[
        local go = GameUtils.GetRedPointGo(self.BtnCatHouse)
        if go then
            KTool.SetActive(go, table.count(t) > 0)
        end
        ]]

        SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting21, false)
        local id = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
        if not isNull(id) then
            SceneManagement:GetInstance():SetActive(id, true)
        end


        KCookie.Set("UIMainInteractionCatDialog", 1)
        Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, {isTrue = false})
        Events.Broadcast(Constants.EventNames.MainHomeScrollActive, { isTrue = false })

        cs_coroutine.start(function()
            CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainInteractionCatDialogUI")
            KTool.SetActive(self.Container, false)
            CfUtils.ChangeMainCamDefalultBlend(0)
            local go = RolesShowMgr:GetInstance():GetInteractiveCam("Push_cat")
            CS.UINavigationBarRoot.Instance:SetActive(false)
            if go then
                KTool.SetActive(go, true)
            end
            coroutine.yield(CS.UnityEngine.WaitForSeconds(0.86))
            CfUtils.ChangeMainCamDefalultBlend(1)
            CS.UINavigationBarRoot.Instance:SetActive(true)
            KTool.SetActive(self.Container, true)
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionCatDialogUI")
        end)

        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
    
        self._catId = checkNumber(argument.catId)    

        local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(id)
        self._go = sceneInstance:GetCacheObjectByName("CatHouseCat")

        if not isNull(self._go) then
            self._ani = KTool.GetOrAddComponent(self._go, typeof(NamedAnimancerComponent))
            self._ani:TryPlay('idle')
        end
        self._catData = nil

        local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        if behaviourAction then
            behaviourAction.UpdateAction = Bind(self, self.Update)
            self._behaviourAction = behaviourAction
        end

        GameUtils.Request(Interfaces.CatHouseCat, {playerCatId = self._catId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local responseData = checkTable(response.data)

            self._catData = responseData.cat
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIMainInteractionCatDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KCookie.Set("UIMainInteractionCatDialog", 0)
        Events.RemoveListener(Constants.EventNames.MainCatCellClick, self._mainCatCellClick)
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, {isTrue = true})
        Events.Broadcast(Constants.EventNames.MainHomeScrollActive, { isTrue = true })

        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMainInteractionCatDialog
